/* Bad Baboon 47 by BadlyWrittenStylesheet — https://uiverse.io/BadlyWrittenStylesheet/bad-baboon-47 */
.container {
  width: 100%;
  height: 100%;

  background-image: radial-gradient(black 55%, #0000),

      linear-gradient(
        135deg,
        red,
        orange,
        yellow,
        lime,
        cyan,
        blue,
        indigo,
        deeppink
      );
  background-size: 100% 0.5%, contain;

}
